/**
 * R8 / resource shrinking for Android release builds is configured through
 * `expo-build-properties` in app.json (not by hand-patching build.gradle).
 * `android/` is regenerated by prebuild, so the only thing worth pinning is
 * that app.json keeps asking for it and keeps the keep-rules that R8 cannot
 * infer: dropping one of them compiles fine and crashes at runtime.
 */
import { describe, it, expect } from '@jest/globals';

type PluginEntry = string | [string, Record<string, unknown>];

// eslint-disable-next-line @typescript-eslint/no-require-imports
const { expo } = require('../../app.json') as { expo: { plugins: PluginEntry[] } };

const entry = expo.plugins.find(
  (p): p is [string, { android: Record<string, unknown> }] =>
    Array.isArray(p) && p[0] === 'expo-build-properties',
);
const android = (entry?.[1].android ?? {}) as {
  enableMinifyInReleaseBuilds?: boolean;
  enableShrinkResourcesInReleaseBuilds?: boolean;
  extraProguardRules?: string;
};

describe('android release shrinking (expo-build-properties)', () => {
  it('enables R8 and resource shrinking in release builds', () => {
    expect(android.enableMinifyInReleaseBuilds).toBe(true);
    expect(android.enableShrinkResourcesInReleaseBuilds).toBe(true);
  });

  it.each([
    '@android.webkit.JavascriptInterface',
    'androidx.work.ListenableWorker',
    'expo.modules.androidliveupdate.**',
    'expo.modules.intipnativedialog.**',
    'expo.modules.intipsystemgestures.**',
    'expo.modules.widgetsglance.**',
    'app.cash.zipline.**',
  ])('keeps %s', (needle) => {
    expect(android.extraProguardRules).toContain(needle);
  });
});
